import { Order } from './types';
export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  list(tenant: string, after?: Pick<Order, 'createdAt' | 'id'>): Order[] {
    return this.rows.filter(row => row.tenant === tenant)
      .filter(row => !after || row.createdAt > after.createdAt ||
        (row.createdAt === after.createdAt && row.id > after.id))
      .sort((a, b) =>
        a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  }
}
